package sum_product_test

import (
    "testing"
    "fmt"
)

// For a given list of integers, return a list consisting of a sum and a product of all the integers in a list.
// Empty sum should be equal to 0 and empty product should be equal to 1.
// >>> sum_product([]int{})
// []interface{}{0, 1}
// >>> sum_product([]int{1, 2, 3, 4})
// []interface{}{10, 24}
func sum_product(numbers []int) []interface{} {
    if len(numbers) == 0 {
        return []interface{}{0, 1}
    }

    sum := 0
    product := 1

    for _, num := range numbers {
        sum += num
        product *= num
    }

    return []interface{}{sum, product}
}
