// true
// >>> is_palindrome("aaaaa")
// true
// >>> is_palindrome("zbcd")
// false
func is_palindrome(text string) bool {
    for i, j := 0, len(text)-1; i < j; i, j = i+1, j-1 {
        if text[i] != text[j] {
            return false
        }
    }
    return true
}
